(function (global) {
  "use strict";
  global.__proxyListFeaturedPhotos = {
    catclass: "data:image/jpeg;base64,",
    duckmath: "data:image/jpeg;base64,",
    studyhub: "data:image/jpeg;base64,",
    voidnetwork: "data:image/jpeg;base64,",
    c00lkidtech: "data:image/jpeg;base64,",
    pgis3: "data:image/jpeg;base64,"
  };
  function applyFeaturedPhotos() {
    var photos = global.__proxyListFeaturedPhotos;
    if (!photos) return;
    var slides = document.querySelectorAll('.featured-slide[data-featured-photo-key]');
    for (var i = 0; i < slides.length; i++) {
      var slide = slides[i];
      var key = slide.getAttribute('data-featured-photo-key');
      var src = key && photos[key];
      if (!src) continue;
      var img = slide.querySelector('.featured-slide-photo');
      if (!img) {
        img = document.createElement('img');
        img.className = 'featured-slide-photo';
        img.alt = '';
        img.width = 1920;
        img.height = 1000;
        slide.insertBefore(img, slide.firstChild);
      }
      img.src = src;
    }
  }
  global.__proxyListApplyFeaturedPhotos = applyFeaturedPhotos;
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyFeaturedPhotos);
  } else {
    applyFeaturedPhotos();
  }
})(typeof window !== 'undefined' ? window : globalThis);
